{{-- Cash/Bank Book register. Expects $rows, $balance, $accountHeader, $emptyText. --}}
<div class="card table-card bank-book-table"><table><caption class="sr-only">Entries</caption><thead><tr><th>Date / recorded</th><th>{{ $accountHeader }}</th><th>From account</th><th>To account / recipient</th><th>Details</th><th>Reference</th><th class="num">Money in</th><th class="num">Money out</th><th class="num">Balance</th></tr></thead><tbody>@forelse($rows as $row)@php($t=$row->transaction)<tr class="{{ $row->unassigned?'bank-row--warning':'' }}"><td>{{ $row->date->format('d M Y') }}<small>{{ $t->created_at->format('d M Y, H:i') }}<br>{{ $t->recorder?->displayName() ?? 'System' }}</small></td><td><strong>{{ $row->bank_account }}</strong>@if($row->unassigned)<small>Choose the correct account on the original entry.</small>@endif</td><td>{{ $row->from_account }}</td><td>{{ $row->to_account }}</td><td>{{ $row->details ?: '—' }}<small>{{ Str::headline($t->transaction_category ?: $t->type) }}</small></td><td>{{ $t->reference ?: '—' }}</td><td class="num">{{ $row->debit?'UGX '.number_format($row->debit):'—' }}</td><td class="num">{{ $row->credit?'UGX '.number_format($row->credit):'—' }}</td><td class="num"><strong>@money($row->running_balance)</strong></td></tr>@empty<tr><td colspan="9">{{ $emptyText }}</td></tr>@endforelse</tbody><tfoot><tr><th colspan="6">Shown entries</th><th class="num">@money($rows->sum('debit'))</th><th class="num">@money($rows->sum('credit'))</th><th class="num">@money($balance)</th></tr></tfoot></table></div>
